<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $case ? 'Edit' : 'Add' ?> Case — Lex Factum</title><link rel="stylesheet" href="<?= base_url('styles.css') ?>"></head><body><div class="crm-wrap"><div class="eyebrow">CRM · Matter</div><h1><?= $case ? 'Edit Case' : 'Add Case' ?></h1><form method="post" action="<?= $action ?>"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><div class="form-grid"><label>Client<select name="client_id" required><?php foreach($clients as $c): ?><option value="<?= $c['id'] ?>" <?= (string)old('client_id',$case['client_id']??'')===(string)$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach; ?></select></label><label>Case Number<input name="case_number" value="<?= esc(old('case_number',$case['case_number']??'')) ?>"></label><label>Title<input name="title" required maxlength="200" value="<?= esc(old('title',$case['title']??'')) ?>"></label><label>Court<input name="court" value="<?= esc(old('court',$case['court']??'')) ?>"></label><label>Case Type<input name="case_type" value="<?= esc(old('case_type',$case['case_type']??'')) ?>"></label><label>Filing Date<input type="date" name="filing_date" value="<?= esc(old('filing_date',$case['filing_date']??'')) ?>"></label><label>Status<select name="status"><?php foreach(['open','active','on_hold','closed'] as $s): ?><option value="<?= $s ?>" <?= old('status',$case['status']??'open')===$s?'selected':'' ?>><?= ucwords(str_replace('_',' ',$s)) ?></option><?php endforeach; ?></select></label><label>Description<textarea name="description"><?= esc(old('description',$case['description']??'')) ?></textarea></label></div><button type="submit">Save Case</button> <a href="<?= site_url('admin/crm/cases') ?>">Cancel</a></form></div><style>.crm-wrap{max-width:1000px;margin:110px auto;padding:0 24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:25px 0}.form-grid label{display:flex;flex-direction:column;gap:7px}.form-grid textarea{min-height:110px}input,select,textarea{padding:12px;border-radius:9px;border:1px solid #aaa;background:rgba(255,255,255,.06);color:inherit}button{padding:12px 18px;border-radius:9px;border:0;cursor:pointer}@media(max-width:700px){.form-grid{grid-template-columns:1fr}}</style></body></html>
